# Rule 4 — Pod OOMKilled (P0)
# ─────────────────────────────────────────────────────────────────────────
# GMP no tiene kube-state-metrics nativo pero sí `kubernetes.io/anthos/*`
# metrics que expone Google Managed Cilium/Anthos. El metric name canónico
# en prom-style es kubernetes_io:anthos_kube_pod_container_status_last_terminated_reason.
rule {
  name      = "Pod OOMKilled"
  for       = "5m"
  condition = "C"

  data {
    ref_id         = "A"
    datasource_uid = local.gmp_prod_uid
    relative_time_range {
      from = 600
      to   = 0
    }
    model = jsonencode({
      expr          = "max_over_time(kubernetes_io:anthos_kube_pod_container_status_last_terminated_reason{reason=\"OOMKilled\"}[10m])"
      intervalMs    = 30000
      maxDataPoints = 43200
      refId         = "A"
    })
  }

  data {
    ref_id         = "C"
    datasource_uid = "__expr__"
    relative_time_range {
      from = 0
      to   = 0
    }
    model = jsonencode({
      type       = "threshold"
      expression = "A"
      refId      = "C"
      conditions = [{
        evaluator = { params = [0], type = "gt" }
        operator  = { type = "and" }
        query     = { params = ["C"] }
        reducer   = { type = "last" }
        type      = "query"
      }]
    })
  }

  labels = {
    severity = "P0"
    team     = "infra"
  }

  annotations = {
    summary     = "Pod {{ $labels.pod }} en namespace {{ $labels.namespace }} fue OOMKilled"
    description = "Container terminated por OOM. Revisar límites de memoria del deployment y patrones de uso. Vimos 2026-04-23 en auth-domain + backgroundcheck-api."
  }

  no_data_state  = "OK"
  exec_err_state = "OK"
  is_paused      = false
}

