# Rule 3 — Disco de GCE VM >80% usado (P1)
# ─────────────────────────────────────────────────────────────────────────
# Datasource: cloud-monitoring-main (stackdriver) — el Ops Agent envía
# agent.googleapis.com/disk/percent_used a Google Cloud Monitoring de
# forma nativa. Usar GMP no funcionó porque el agent no exportaba a
# Prometheus (ver commit d58295d).
# Scope: defaultProject = prod-apps-454414. Para cubrir otros proyectos
# (security-454414, liftit-bi, etc.) habría que replicar la rule con
# projectName distinto o agregar `multipleProjectIds` en el plugin.
rule {
  name      = "Disk usage > 80%"
  for       = "15m"
  condition = "C"

  data {
    ref_id         = "A"
    datasource_uid = "cloud-monitoring-main"
    relative_time_range {
      from = 900
      to   = 0
    }
    model = jsonencode({
      refId     = "A"
      queryType = "metrics"
      metricQuery = {
        projectName        = "prod-apps-454414"
        metricType         = "agent.googleapis.com/disk/percent_used"
        filters            = ["metric.label.state", "=", "used"]
        alignmentPeriod    = "cloud-monitoring-auto"
        perSeriesAligner   = "ALIGN_MEAN"
        crossSeriesReducer = "REDUCE_MAX"
        # Label correcto es instance_id (numeric), no instance_name — el
        # resource type gce_instance no expone instance_name en metric labels.
        # Para traducir id→name se resuelve en el bot durante investigación.
        groupBys = [
          "resource.label.instance_id",
          "resource.label.zone",
          "metric.label.device",
        ]
        aliasBy    = "{{resource.label.instance_id}} {{metric.label.device}}"
        editorMode = "visual"
      }
    })
  }

  data {
    ref_id         = "C"
    datasource_uid = "__expr__"
    relative_time_range {
      from = 0
      to   = 0
    }
    model = jsonencode({
      type       = "threshold"
      expression = "A"
      refId      = "C"
      conditions = [{
        evaluator = { params = [80], type = "gt" }
        operator  = { type = "and" }
        query     = { params = ["C"] }
        reducer   = { type = "last" }
        type      = "query"
      }]
    })
  }

  labels = {
    severity = "P1"
    team     = "infra"
  }

  annotations = {
    summary     = "Disco {{ $labels.device }} >80% en VM instance_id={{ $labels.instance_id }} zone={{ $labels.zone }}"
    description = "El filesystem del dispositivo {{ $labels.device }} está por encima del 80% sostenido por 15min. Instance GCE id {{ $labels.instance_id }} (traducir a nombre con `gcloud compute instances list --filter id=<id>`). Escalar antes de que llegue a 90%."
  }

  no_data_state  = "OK"
  exec_err_state = "OK"
  is_paused      = false
}

# ─────────────────────────────────────────────────────────────────────────

