# Custom queries para alertas proactivas Liftit (TI-1446).
# Todas usan pg_stat_* views (shared memory) — load negligible.

pg_stat_activity_by_app:
  query: |
    SELECT
      COALESCE(datname, 'unknown') AS datname,
      COALESCE(state, 'none') AS state,
      COALESCE(NULLIF(application_name, ''), 'unknown') AS application_name,
      COUNT(*) AS count
    FROM pg_stat_activity
    WHERE backend_type = 'client backend'
    GROUP BY datname, state, application_name
  metrics:
    - datname: {usage: LABEL, description: 'Database name'}
    - state: {usage: LABEL, description: 'Connection state'}
    - application_name: {usage: LABEL, description: 'Application name'}
    - count: {usage: GAUGE, description: 'Number of connections for this tuple'}

pg_connection_saturation:
  query: |
    SELECT
      (SELECT count(*) FROM pg_stat_activity) AS current_connections,
      current_setting('max_connections')::int AS max_connections,
      round((SELECT count(*) FROM pg_stat_activity)::numeric / current_setting('max_connections')::numeric, 4) AS saturation_ratio
  metrics:
    - current_connections: {usage: GAUGE, description: 'Current active connections'}
    - max_connections: {usage: GAUGE, description: 'max_connections setting'}
    - saturation_ratio: {usage: GAUGE, description: 'current/max (0..1)'}

pg_replication_status:
  query: |
    SELECT
      COALESCE(host(client_addr)::text, pid::text) AS replica_addr,
      COALESCE(state, 'unknown') AS state,
      COALESCE(EXTRACT(EPOCH FROM (now() - reply_time)), 0) AS reply_lag_seconds,
      COALESCE(EXTRACT(EPOCH FROM write_lag), 0) AS write_lag_seconds,
      COALESCE(EXTRACT(EPOCH FROM flush_lag), 0) AS flush_lag_seconds,
      COALESCE(EXTRACT(EPOCH FROM replay_lag), 0) AS replay_lag_seconds
    FROM pg_stat_replication
  metrics:
    - replica_addr: {usage: LABEL, description: 'Replica application_name'}
    - state: {usage: LABEL, description: 'Replication state (streaming, catchup, ...)'}
    - reply_lag_seconds: {usage: GAUGE, description: 'Seconds since last reply from replica'}
    - write_lag_seconds: {usage: GAUGE, description: 'Write lag between primary and replica'}
    - flush_lag_seconds: {usage: GAUGE, description: 'Flush lag'}
    - replay_lag_seconds: {usage: GAUGE, description: 'Replay lag (useful for read-after-write)'}

pg_blocking_queries:
  query: |
    SELECT
      COUNT(*) FILTER (WHERE blocked_duration_seconds > 60) AS blocked_over_60s,
      COUNT(*) FILTER (WHERE blocked_duration_seconds > 120) AS blocked_over_120s,
      COUNT(*) FILTER (WHERE blocked_duration_seconds > 300) AS blocked_over_300s
    FROM (
      SELECT
        EXTRACT(EPOCH FROM (now() - query_start)) AS blocked_duration_seconds
      FROM pg_stat_activity
      WHERE wait_event_type = 'Lock'
    ) sub
  metrics:
    - blocked_over_60s: {usage: GAUGE, description: 'Queries waiting on lock >60s'}
    - blocked_over_120s: {usage: GAUGE, description: 'Queries waiting on lock >120s'}
    - blocked_over_300s: {usage: GAUGE, description: 'Queries waiting on lock >300s'}

pg_idle_in_tx_by_app:
  query: |
    SELECT
      COALESCE(NULLIF(application_name, ''), 'unknown') AS application_name,
      COUNT(*) AS count
    FROM pg_stat_activity
    WHERE state = 'idle in transaction'
    GROUP BY application_name
  metrics:
    - application_name: {usage: LABEL, description: 'Application with idle-in-tx'}
    - count: {usage: GAUGE, description: 'Number of idle-in-transaction connections'}
