  # ─────────────────────────────────────────────────────────────────────────
  # TI-1446 — PG metrics (wave DB). Scrapeadas desde postgres_exporter v0.17.1
  # en la VM lms-db via Ops Agent → Cloud Monitoring prometheus_target.
  # Metric type prefix: prometheus.googleapis.com/<name>/gauge
  # Datasource: cloud-monitoring-main. Scope fijo a prod-apps-454414 (donde
  # vive la VM lms-db). Ver databases/vm/files/monitoring/README.md.
  # ─────────────────────────────────────────────────────────────────────────

  # Rule 10 — PG idle-in-tx leak por aplicación (P0)
  # ─────────────────────────────────────────────────────────────────────────
  # Conexiones en estado 'idle in transaction' agrupadas por application_name.
  # Umbral: >10 sostenido 5min. Cada conexión idle-in-tx tiene locks/snapshots
  # activos y bloquea VACUUM + escala row bloat. Root-cause típico: app no
  # cierra transacción tras error; gunicorn worker timeout; pool config mal.
  # Observado 2026-04-23: orders-domain + services-domain (correlación con
  # pg_advisory_xact_lock + WORKER TIMEOUT gunicorn).
  rule {
    name      = "PG idle-in-tx leak"
    for       = "5m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = "cloud-monitoring-main"
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        refId     = "A"
        queryType = "metrics"
        metricQuery = {
          projectName        = "prod-apps-454414"
          metricType         = "prometheus.googleapis.com/pg_idle_in_tx_by_app_count/gauge"
          alignmentPeriod    = "cloud-monitoring-auto"
          perSeriesAligner   = "ALIGN_MEAN"
          crossSeriesReducer = "REDUCE_MAX"
          groupBys = [
            "metric.label.application_name",
          ]
          aliasBy    = "{{metric.label.application_name}}"
          editorMode = "visual"
        }
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [10], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P0"
      team     = "infra"
    }

    annotations = {
      summary     = "PG idle-in-tx >10 sostenido en app {{ $labels.application_name }}"
      description = "Aplicación {{ $labels.application_name }} tiene >10 conexiones en estado 'idle in transaction' sostenido 5min sobre lms-db. Bloquea VACUUM y provoca bloat/locks. Investigar: transacciones no cerradas por error, gunicorn worker timeout, pool saturado. Evidencia correlacionada: ver logs + postgres-deep."
    }

    no_data_state  = "OK"
    exec_err_state = "OK"
    is_paused      = false
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 11 — PG connections saturation (P1)
  # ─────────────────────────────────────────────────────────────────────────
  # Ratio current_connections / max_connections. lms-db: max_connections=850.
  # Umbral 0.80 = 680 conexiones. A 0.90 falta capacidad para reintentos,
  # pgbouncer failover, o spikes de trabajo nuevo.
  rule {
    name      = "PG connections saturation > 80%"
    for       = "5m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = "cloud-monitoring-main"
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        refId     = "A"
        queryType = "metrics"
        metricQuery = {
          projectName        = "prod-apps-454414"
          metricType         = "prometheus.googleapis.com/pg_connection_saturation_saturation_ratio/gauge"
          alignmentPeriod    = "cloud-monitoring-auto"
          perSeriesAligner   = "ALIGN_MEAN"
          crossSeriesReducer = "REDUCE_MEAN"
          groupBys           = []
          aliasBy            = "saturation_ratio"
          editorMode         = "visual"
        }
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [0.80], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P1"
      team     = "infra"
    }

    annotations = {
      summary     = "PG connection saturation > 80% (max_connections=850)"
      description = "Saturación de conexiones a lms-db sostenida 5min. Investigar con postgres-deep qué app concentra conexiones (pg_stat_activity_by_app_count by application_name). Considerar pgbouncer o aumentar max_connections si es growth legítimo."
    }

    no_data_state  = "OK"
    exec_err_state = "OK"
    is_paused      = false
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 12 — PG replication replay lag > 30s (P1)
  # ─────────────────────────────────────────────────────────────────────────
  # Usamos replay_lag (no reply_lag): replay_lag mide lag efectivo que afecta
  # read-after-write en las replicas. Observado 2026-04-23: 0.04s-0.06s
  # baseline healthy. Umbral 30s = problemas IO/CPU en replica o red saturada.
  rule {
    name      = "PG replication replay lag > 30s"
    for       = "5m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = "cloud-monitoring-main"
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        refId     = "A"
        queryType = "metrics"
        metricQuery = {
          projectName        = "prod-apps-454414"
          metricType         = "prometheus.googleapis.com/pg_replication_status_replay_lag_seconds/gauge"
          alignmentPeriod    = "cloud-monitoring-auto"
          perSeriesAligner   = "ALIGN_MAX"
          crossSeriesReducer = "REDUCE_MAX"
          groupBys = [
            "metric.label.replica_addr",
          ]
          aliasBy    = "{{metric.label.replica_addr}}"
          editorMode = "visual"
        }
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [30], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P1"
      team     = "infra"
    }

    annotations = {
      summary     = "PG replica {{ $labels.replica_addr }} replay_lag > 30s sostenido"
      description = "La replica {{ $labels.replica_addr }} está atrasada >30s aplicando WAL. Afecta read-after-write en apps que leen de replica. Investigar IO/CPU en la VM replica, saturación de red con primary, queries largas en replica bloqueando recovery."
    }

    no_data_state  = "OK"
    exec_err_state = "OK"
    is_paused      = false
  }

  # ─────────────────────────────────────────────────────────────────────────
  # Rule 13 — PG blocking queries >2min (P0)
  # ─────────────────────────────────────────────────────────────────────────
  # Count de queries esperando lock por >120s. Cualquier valor >0 ya es P0:
  # indica contención real (advisory locks, row locks, DDL). Ventana corta 2m
  # para reaccionar rápido — blocking sostenido escala a stampede de timeouts.
  rule {
    name      = "PG blocking queries > 2min"
    for       = "2m"
    condition = "C"

    data {
      ref_id         = "A"
      datasource_uid = "cloud-monitoring-main"
      relative_time_range {
        from = 600
        to   = 0
      }
      model = jsonencode({
        refId     = "A"
        queryType = "metrics"
        metricQuery = {
          projectName        = "prod-apps-454414"
          metricType         = "prometheus.googleapis.com/pg_blocking_queries_blocked_over_120s/gauge"
          alignmentPeriod    = "cloud-monitoring-auto"
          perSeriesAligner   = "ALIGN_MAX"
          crossSeriesReducer = "REDUCE_MAX"
          groupBys           = []
          aliasBy            = "blocked_over_120s"
          editorMode         = "visual"
        }
      })
    }

    data {
      ref_id         = "C"
      datasource_uid = "__expr__"
      relative_time_range {
        from = 0
        to   = 0
      }
      model = jsonencode({
        type       = "threshold"
        expression = "A"
        refId      = "C"
        conditions = [{
          evaluator = { params = [0], type = "gt" }
          operator  = { type = "and" }
          query     = { params = ["C"] }
          reducer   = { type = "last" }
          type      = "query"
        }]
      })
    }

    labels = {
      severity = "P0"
      team     = "infra"
    }

    annotations = {
      summary     = "PG: queries bloqueadas >2min en lms-db"
      description = "Hay {{ $value }} queries esperando lock por más de 120s en lms-db. Contención real (advisory locks, row locks, DDL pending). Escalar a postgres-deep: pg_blocking_pids() + pg_stat_activity WHERE wait_event_type='Lock'. Observado pattern 2026-04-23: services-domain con pg_advisory_xact_lock + worker timeouts gunicorn."
    }

    no_data_state  = "OK"
    exec_err_state = "OK"
    is_paused      = false
  }
}

